import { createHmac, timingSafeEqual } from "node:crypto";
import type { Prisma } from "@prisma/client";
import { prisma } from "@/lib/db";
import { env } from "@/lib/env";

/**
 * Unipile API v2 webhooks.
 * Docs: https://developer.unipile.com/v2.0/docs/configure-a-webhook#secure-your-endpoint
 *
 * Signature header: `unipile-signature: t=<unix seconds>,v0=<hex>` where
 * v0 = HMAC_SHA256(endpoint_secret, `${t}.${raw_body}`). The endpoint secret is
 * generated by Unipile and shown on the webhook endpoint in the dashboard.
 */
export const UNIPILE_SIGNATURE_HEADER = "unipile-signature";

/** Reject signatures older than this (matches Unipile's example). */
const MAX_SIGNATURE_AGE_SECONDS = 300;

/** Bodies past this are stored truncated (Unipile payloads are a few KB). */
const MAX_BODY_CHARS = 64 * 1024;

const REDACTED_HEADERS = new Set(["cookie", "authorization"]);

/**
 * v2 event envelope. `payload` depends on `type`:
 * - relation.new: UserRelation; `user.id` is the new connection.
 * - message.new: Message; `sender.id` is the author, `is_sender` is true when
 *   the linked account itself sent it (then the counterparty isn't in the payload).
 * In both, the id is the LinkedIn provider id we store on prospects.
 */
type UnipileWebhookEvent = {
  id?: unknown;
  type?: unknown;
  account_id?: unknown;
  payload?: {
    user?: { id?: unknown };
    sender?: { id?: unknown };
    is_sender?: unknown;
  } | null;
};

/** The other LinkedIn member this event is about, if the payload names one. */
function counterpartyProviderId(event: UnipileWebhookEvent | null): string | null {
  const payload = event?.payload;
  const relationUser = str(payload?.user?.id);
  if (relationUser) {
    return relationUser;
  }
  return payload?.is_sender === false ? str(payload.sender?.id) : null;
}

function str(value: unknown): string | null {
  return typeof value === "string" && value.trim().length > 0 ? value : null;
}

function parseSignatureHeader(header: string | null) {
  if (!header) {
    return null;
  }
  let timestamp: string | null = null;
  const signatures: string[] = [];
  for (const part of header.split(",")) {
    const [key, ...rest] = part.trim().split("=");
    const value = rest.join("=");
    if (key === "t") {
      timestamp = value;
    } else if (key === "v0" && value) {
      signatures.push(value);
    }
  }
  return timestamp && signatures.length > 0 ? { timestamp, signatures } : null;
}

export function signatureValid(header: string | null, rawBody: string): boolean {
  const secret = env.unipileWebhookSecret;
  const parsed = parseSignatureHeader(header);
  if (!secret || !parsed) {
    return false;
  }

  const expected = Buffer.from(
    createHmac("sha256", secret)
      .update(`${parsed.timestamp}.${rawBody}`)
      .digest("hex"),
  );
  const matches = parsed.signatures.some((signature) => {
    const received = Buffer.from(signature);
    return received.length === expected.length && timingSafeEqual(received, expected);
  });
  if (!matches) {
    return false;
  }

  const ageSeconds = Math.abs(Date.now() / 1000 - Number(parsed.timestamp));
  return Number.isFinite(ageSeconds) && ageSeconds <= MAX_SIGNATURE_AGE_SECONDS;
}

function safeHeaders(headers: Headers): Record<string, string> {
  const out: Record<string, string> = {};
  headers.forEach((value, key) => {
    out[key] = REDACTED_HEADERS.has(key.toLowerCase()) ? "[redacted]" : value;
  });
  return out;
}

function parse(rawBody: string): UnipileWebhookEvent | null {
  try {
    const value: unknown = JSON.parse(rawBody);
    return value && typeof value === "object" && !Array.isArray(value)
      ? (value as UnipileWebhookEvent)
      : null;
  } catch {
    return null;
  }
}

/** Match the event to our user (by Unipile account) and prospect (by LinkedIn provider id). */
async function resolveOwners(event: UnipileWebhookEvent | null) {
  const accountId = str(event?.account_id);
  if (!accountId) {
    return { userId: null, prospectId: null };
  }
  const connection = await prisma.integrationConnection.findUnique({
    where: { externalAccountId: accountId },
    select: { userId: true },
  });
  if (!connection) {
    return { userId: null, prospectId: null };
  }
  const providerId = counterpartyProviderId(event);
  const prospect = providerId
    ? await prisma.prospect.findFirst({
        where: { userId: connection.userId, linkedinProviderId: providerId },
        select: { id: true },
      })
    : null;
  return { userId: connection.userId, prospectId: prospect?.id ?? null };
}

/**
 * Records every inbound Unipile webhook. `verified` always reflects whether the
 * signature checked out. A request is accepted (matched to users, 2xx) when it is
 * verified, or when checking is turned off with UNIPILE_WEBHOOK_VERIFY="false".
 */
export async function recordUnipileWebhook(request: Request) {
  // Signature is over the exact raw body, so read text before any parsing.
  const fullBody = await request.text();
  const rawBody = fullBody.slice(0, MAX_BODY_CHARS);
  const verified = signatureValid(
    request.headers.get(UNIPILE_SIGNATURE_HEADER),
    fullBody,
  );
  const accepted = verified || !env.unipileWebhookVerify;
  const event = fullBody.length <= MAX_BODY_CHARS ? parse(rawBody) : null;

  const owners = accepted
    ? await resolveOwners(event)
    : { userId: null, prospectId: null };

  const record = await prisma.webhookEvent.create({
    data: {
      provider: "unipile",
      event: str(event?.type),
      externalAccountId: str(event?.account_id),
      verified,
      payload: (event ?? undefined) as Prisma.InputJsonValue | undefined,
      rawBody,
      headers: safeHeaders(request.headers),
      userId: owners.userId,
      prospectId: owners.prospectId,
    },
    select: { id: true },
  });

  return { id: record.id, accepted };
}
